import React, { useState, useEffect } from 'react';

const Hero = () => {
  const [displayText, setDisplayText] = useState('');
  const [currentIndex, setCurrentIndex] = useState(0);
  const [showCircle, setShowCircle] = useState(true);
  const [showButton, setShowButton] = useState(false);

  const fullText = "You wake up in an unknown place, trapped in this strange world.";

  // 圓圈退去效果
  useEffect(() => {
    const timer = setTimeout(() => {
      setShowCircle(false);
    }, 2000);

    return () => clearTimeout(timer);
  }, []);

  // 打字效果
  useEffect(() => {
    if (!showCircle) {
      const timer = setTimeout(() => {
        if (currentIndex < fullText.length) {
          setDisplayText(prev => prev + fullText[currentIndex]);
          setCurrentIndex(prev => prev + 1);
        } else {
          setTimeout(() => {
            setShowButton(true);
          }, 2000);
        }
      }, 100);

      return () => clearTimeout(timer);
    }
  }, [currentIndex, fullText.length, showCircle]);

  const handleButtonClick = () => {
    // 可以添加其他功能，比如顯示更多信息或重新開始動畫
    console.log('Button clicked!');
  };

  return (
    <section id="hero" className="min-h-screen flex items-center justify-center bg-black relative overflow-hidden">
      {/* 黑色圓圈退去效果 */}
      {showCircle && (
        <div className="absolute inset-0 bg-black flex items-center justify-center">
          <div className="w-96 h-96 bg-black rounded-full animate-circle-shrink"></div>
        </div>
      )}

      {/* 山洞背景效果 */}
      {!showCircle && (
        <div className="absolute inset-0">
          {/* 山洞頂部 */}
          <div className="absolute top-0 left-0 w-full h-32 bg-gray-800">
            <div className="absolute top-16 left-1/4 w-8 h-8 bg-gray-700 transform rotate-45"></div>
            <div className="absolute top-20 left-1/3 w-6 h-6 bg-gray-700 transform rotate-45"></div>
            <div className="absolute top-12 left-1/2 w-10 h-10 bg-gray-700 transform rotate-45"></div>
            <div className="absolute top-18 left-2/3 w-7 h-7 bg-gray-700 transform rotate-45"></div>
            <div className="absolute top-14 left-3/4 w-9 h-9 bg-gray-700 transform rotate-45"></div>
          </div>

          {/* 山洞側壁 */}
          <div className="absolute left-0 top-32 w-32 h-full bg-gray-800">
            <div className="absolute top-20 left-8 w-4 h-4 bg-gray-700"></div>
            <div className="absolute top-32 left-12 w-6 h-6 bg-gray-700"></div>
            <div className="absolute top-48 left-6 w-5 h-5 bg-gray-700"></div>
            <div className="absolute top-64 left-10 w-7 h-7 bg-gray-700"></div>
            <div className="absolute top-80 left-4 w-3 h-3 bg-gray-700"></div>
          </div>

          <div className="absolute right-0 top-32 w-32 h-full bg-gray-800">
            <div className="absolute top-24 right-8 w-5 h-5 bg-gray-700"></div>
            <div className="absolute top-40 right-12 w-4 h-4 bg-gray-700"></div>
            <div className="absolute top-56 right-6 w-6 h-6 bg-gray-700"></div>
            <div className="absolute top-72 right-10 w-3 h-3 bg-gray-700"></div>
            <div className="absolute top-88 right-4 w-5 h-5 bg-gray-700"></div>
          </div>

          {/* 地面 */}
          <div className="absolute bottom-0 left-0 w-full h-24 bg-gray-900">
            <div className="absolute bottom-4 left-1/4 w-2 h-2 bg-gray-600"></div>
            <div className="absolute bottom-8 left-1/3 w-1 h-1 bg-gray-600"></div>
            <div className="absolute bottom-6 left-1/2 w-3 h-3 bg-gray-600"></div>
            <div className="absolute bottom-10 left-2/3 w-2 h-2 bg-gray-600"></div>
            <div className="absolute bottom-5 left-3/4 w-1 h-1 bg-gray-600"></div>
          </div>

          {/* 遠處的光點 */}
          <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2">
            <div className="w-2 h-2 bg-yellow-300 rounded-full opacity-60 animate-pulse"></div>
            <div className="absolute top-4 left-8 w-1 h-1 bg-yellow-200 rounded-full opacity-40 animate-pulse animation-delay-1000"></div>
            <div className="absolute top-8 left-16 w-1 h-1 bg-yellow-200 rounded-full opacity-30 animate-pulse animation-delay-2000"></div>
          </div>
        </div>
      )}

      {/* 文字內容 */}
      {!showCircle && (
        <div className="relative z-10 text-center text-white px-6 max-w-4xl mx-auto">
          {/* 打字效果文字 */}
          <div className="mb-8">
            <h1 className="text-3xl md:text-5xl font-bold mb-4 leading-relaxed text-shadow">
              <span className="inline-block">
                {displayText}
                <span className="animate-pulse text-white">|</span>
              </span>
            </h1>
          </div>

          {/* 按鈕 */}
          {showButton && (
            <div className="animate-fade-in-up">
              <button 
                className="group relative inline-flex items-center justify-center px-8 py-4 text-lg font-semibold text-black bg-white rounded-full hover:bg-gray-200 transform hover:scale-105 transition-all duration-300 shadow-lg hover:shadow-xl"
                onClick={handleButtonClick}
              >
                <span className="relative z-10 flex items-center">
                  Continue
                  <svg className="ml-2 w-5 h-5 group-hover:translate-x-1 transition-transform duration-300" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7l5 5m0 0l-5 5m5-5H6" />
                  </svg>
                </span>
              </button>
            </div>
          )}
        </div>
      )}
    </section>
  );
};

export default Hero;
